psql "$DB_URL" <<'SQLEOF'
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_type WHERE typname = 'UserStatus') THEN
    CREATE TYPE "UserStatus" AS ENUM ('PENDING', 'ACTIVE', 'SUSPENDED');
    RAISE NOTICE 'Enum UserStatus criado';
  ELSE
    RAISE NOTICE 'Enum UserStatus ja existe';
  END IF;
END $$;

DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name='User' AND column_name='status') THEN
    ALTER TABLE "User" ADD COLUMN status "UserStatus";
    UPDATE "User" SET status = 'ACTIVE';
    ALTER TABLE "User" ALTER COLUMN status SET NOT NULL;
    ALTER TABLE "User" ALTER COLUMN status SET DEFAULT 'PENDING';
    RAISE NOTICE 'Coluna status adicionada';
  ELSE
    RAISE NOTICE 'Coluna status ja existe';
  END IF;
END $$;

INSERT INTO _prisma_migrations (id, checksum, finished_at, migration_name, logs, rolled_back_at, started_at, applied_steps_count)
SELECT gen_random_uuid()::text, 'manual-2026-03-29', NOW(), '20260329000000_add_user_status', NULL, NULL, NOW(), 1
WHERE NOT EXISTS (SELECT 1 FROM _prisma_migrations WHERE migration_name = '20260329000000_add_user_status');

SELECT id, name, email, role, status FROM "User" ORDER BY id;
